'use strict';

const _get = require('lodash/get');

const stringify = require('../../stringify');
const { getTransport } = require('./transport');

// TODO: Написать тесты на стрим и прогнать benchmark
// https://st.yandex-team.ru/TOOLBOX-123
/**
 * Стрим для yandex-logger, позволяющий слать ошибки в error-booster.
 *
 * @param {YandexLoggerErrorBoosterStreamConfig} [config]
 * @returns {Object}
 */
module.exports = config => {
    config = config || {};

    const transport = getTransport({
        socketType: config.socketType,
        socketPath: config.socketPath,
        socketHost: config.socketHost,
        socketPort: config.socketPort,
        maxTotalSockets: config.maxTotalSockets,
    });

    const metaKeys = config.metaKeys || ['reqid'];

    function getMeta(data) {
        const meta = {};
        for (let i = 0; i < metaKeys.length; i++) {
            const key = metaKeys[i];
            if (key in data) {
                meta[key] = data[key];
            }
        }
        return meta;
    }

    return {
        /**
         * @param {Object} record
         * @returns {undefined}
         */
        write(record) {
            // eslint-disable-next-line @typescript-eslint/no-use-before-define
            const dataFromRequest = record.req ? parseDataFromRequest(record.req) : {};

            // Поля, которые не понимает error-booster будут проигнорированы
            // Список полей: https://wiki.yandex-team.ru/error-booster/error-how-to/#kakispolzovat
            const data = {
                // Эти два поля зависят от мидлвар req и err, поэтому даём возможность их переопределять
                reqid: record.requestId,
                stack: record.err && record.err.stack,

                ...dataFromRequest,
                ...record,

                additional: Object.assign(
                    {},
                    _get(config, 'fields.additional', {}),
                    record.additional
                ),

                pid: record.pid,
                dc: (record.hostname.match(/\bsas|vla|man|iva|myt\b/) || [])[0],
                host: record.hostname,
                language: 'nodejs',
                level: record.levelName.toLowerCase(),
                service: config.service,

                // Обязательные поля
                project: config.project,
                message: record.msg || 'Empty error',
                timestamp: record.date.getTime(),
            };

            transport(stringify(data), getMeta(data));
        },
    };
};

/**
 * Сбор дополнительных данных, которые были подготовлены мидлварой req
 * @param {Req} req - Объект с данными о запросе
 * @returns {Object}
 * @private
 */
function parseDataFromRequest(req) {
    return {
        method: req.method,
        url: req.url,
        useragent: req.headers && req.headers['user-agent'],
        yandexuid: req.yandexuid,
    };
}

/**
 * @typedef {Object} YandexLoggerErrorBoosterStreamConfig
 * @property {String} [project]  - Ваш проект в error-booster'e
 * @property {String} [socketType] - Тип сокета ('http' или 'unix_dgram'), по умолчанию 'unix_dgram'
 * @property {String} [socketHost] - Хост сокета, по умолчанию 'localhost'
 * @property {Number} [socketPort] - Порт сокета, по умолчанию '12522'
 * @property {String} [socketPath] - Путь до сокета, по умолчанию '/socketPath'
 * @property {Number} [maxTotalSockets] - Максимальное количество одновременных сокетов к unified agent,
                                          по умолчанию '8'
 * @property {String[]} [metaKeys] - Ключи, которые нужно скопировать в заголовки запроса (unified-agent
                                     их затем сможет переложить в метафлаги сообщения).
                                     Работает только для 'http', по-умолчанию ['reqid']
 * @property {String} [service] - Имя сервиса, внутри проекта
 */

/**
 * @typedef {Object} Req
 * @property {String} [method]    - Метод запроса
 * @property {String} [url]       - Полный адрес страницы, включая протокол и хост
 * @property {Object} [headers]   - Заголовки запроса
 * @property {String} [yandexuid] - Значение yandexuid из кук пользователя
 */
